//github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/networking/action_handlers.lua#L1033-L1072 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/lib/ruleset_utils.lua#L28-L32 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayerAPI-Server/blob/d664c29523b827d53dfa1a181e5b2baf1aefac4f/src/actionHandlers.ts#L696-L719",status:"VERIFIED"},{key:"timer.threshold",value:"MLB forces timer_display_threshold=180 = base, so start is broadcast immediately (pending only if timer > threshold)",source:"specs/mlb-s4.txt:21 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/rulesets/majorleague.lua#L28 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/networking/action_handlers.lua#L1363-L1370",status:"VERIFIED"},{key:"timer.tick",value:"countdown runs on each client (dt-based); ticks only when someone pressed; never during the PvP (Nemesis) blind; stops if you reached PvP, are ready, and did not press yourself; does not tick on game over; no animation budget in legacy mode",source:"specs/mlb-s4.txt:22 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/ui/game/timer.lua#L406-L413 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/ui/game/timer.lua#L446-L449 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/ui/game/timer.lua#L468-L470",status:"VERIFIED"},{key:"timer.pauses",value:"timer flags cleared on disconnect/reconnect (enemyDisconnected, reconnecting, rejoinedLobby)",source:"specs/mlb-s4.txt:23 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/networking/action_handlers.lua#L95-L106 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/networking/action_handlers.lua#L150-L160 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/networking/action_handlers.lua#L250-L262",status:"VERIFIED"},{key:"timer.expiry",value:"at 0 -> timer_consumed=true; if opponent had timered you: if timers_forgiven < timer_forgiveness (S4: 0) forgive, else send failTimer -> server loseLife('timer'); 0 lives -> winGame/loseGame",source:"specs/mlb-s4.txt:24 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/ui/game/timer.lua#L484-L499 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayerAPI-Server/blob/d664c29523b827d53dfa1a181e5b2baf1aefac4f/src/actionHandlers.ts#L721-L743",status:"VERIFIED"},{key:"timer.expiry_pvp",value:"legacy timer never ticks in PvP, so S4 PvP-timer expiry path (failPvPTimer) is not reachable",source:"specs/mlb-s4.txt:25 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/ui/game/timer.lua#L446",status:"VERIFIED"},{key:"timer.once_per_cycle",value:"after expiry timer_consumed blocks ticking until endPvP / begin PvP blind reset timer to 180 and timer_consumed=false; at most 1 timer life per round (timerLivesBlocker, reset on newRound); a timer life and a blind life can both be lost in one round",source:"specs/mlb-s4.txt:26 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/networking/action_handlers.lua#L328-L334 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayer/blob/3dff16a99edde91894e0ccf94cc9a9171443070b/networking/action_handlers.lua#L496-L502 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayerAPI-Server/blob/d664c29523b827d53dfa1a181e5b2baf1aefac4f/src/Client.ts#L50-L55 ; https://github.com/Balatro-Multiplayer/BalatroMultiplayerAPI-Server/blob/d664c29523b827d53dfa1a181e5b2baf1aefac4f/src/Client.ts#L113-L124 ; https://gi